/**
 * @summary List AI analysis results
 */
export const getListAiResultsUrl = (params?: ListAiResultsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/ai/results?${stringifiedParams}`
    : `/api/ai/results`;
};

export const listAiResults = async (
  params?: ListAiResultsParams,
  options?: RequestInit,
): Promise<AiAnalysisResult[]> => {
  return customFetch<AiAnalysisResult[]>(getListAiResultsUrl(params), {
    ...options,
    method: "GET",
  });
};

